import{_ as t,c as a,a0 as d,o}from"./chunks/framework.B6JXc2q-.js";const h=JSON.parse('{"title":"ADR-0007：音箱持有播放队列，服务端跟随","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0007-speaker-owned-queue.md","filePath":"adr/0007-speaker-owned-queue.md"}'),l={name:"adr/0007-speaker-owned-queue.md"};function r(c,e,s,i,n,p){return o(),a("div",null,e[0]||(e[0]=[d(`<h1 id="adr-0007-音箱持有播放队列-服务端跟随" tabindex="-1">ADR-0007：音箱持有播放队列，服务端跟随 <a class="header-anchor" href="#adr-0007-音箱持有播放队列-服务端跟随" aria-label="Permalink to &quot;ADR-0007：音箱持有播放队列，服务端跟随&quot;">​</a></h1><ul><li><strong>状态</strong>：Proposed（方向已于 2026-11-22 认可；按“实施步骤”分步落地，每步测试服实机验收，全部完成后改为 Accepted）</li><li><strong>日期</strong>：2026-11-22</li><li><strong>关联</strong>：ADR-0003（Source 抽象）、ADR-0004（状态权威）</li></ul><h2 id="上下文" tabindex="-1">上下文 <a class="header-anchor" href="#上下文" aria-label="Permalink to &quot;上下文&quot;">​</a></h2><h3 id="现状-服务端逐首指挥" tabindex="-1">现状：服务端逐首指挥 <a class="header-anchor" href="#现状-服务端逐首指挥" aria-label="Permalink to &quot;现状：服务端逐首指挥&quot;">​</a></h3><p>服务端每次只向音箱下发<strong>一首</strong>（<code>play_by_music_url</code>，一个 audio item），靠“时长 + <code>delay_sec</code>”（现为固定提前 2 s）的计时器推测歌曲结束，再下发下一首。音箱自带列表循环（<code>loop_type: 1</code>），只有一首的列表会在结尾<strong>从头重放</strong>。</p><p>在测试服（OH2P）上实测得到以下问题：</p><table tabindex="0"><thead><tr><th>问题</th><th>实测</th></tr></thead><tbody><tr><td>切歌晚到，用户听到“当前歌曲从头播几秒再切”</td><td>计时器到点后，服务端切歌需要 3.4–6.4 s，但只提前了 2 s</td></tr><tr><td>小米云间歇卡顿</td><td><code>player_stop</code> 和 <code>play_by_music_url</code> 都会遇到约 31 s 的送达延迟，1 小时内 3 次</td></tr><tr><td>服务端一旦停住，音箱就“单曲循环”</td><td>已修复两处诱因（切歌前停止超时、顺序播放结束），但逐首模型下这类问题会反复出现</td></tr><tr><td>拿不到播放进度</td><td><code>player_get_play_status</code> 只返回 <code>status/volume/loop_type</code>；Jellyfin 不为音箱建立会话；MIoT 规格没有进度</td></tr></tbody></table><p>2026-11-22 已经去掉计时器到点后的状态查询，自动切歌也不再先停止（<code>auto_next_preplay_stop=false</code>），正常时切换时间降到 1–2 s。剩下的延迟在下发命令本身（0.4–7 s，偶发 31 s），只要逐首经过小米云就消除不了。</p><h3 id="实验结论-测试服-oh2p-2026-11-22" tabindex="-1">实验结论（测试服 OH2P，2026-11-22） <a class="header-anchor" href="#实验结论-测试服-oh2p-2026-11-22" aria-label="Permalink to &quot;实验结论（测试服 OH2P，2026-11-22）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>结论</th></tr></thead><tbody><tr><td>一个 <code>player_play_music</code> 带多个 audio item</td><td>✅ 音箱放完一首后<strong>在本地</strong>接着放下一首，不经过云端</td></tr><tr><td><code>startaudioid</code> 指定起始项</td><td>✅ 有效</td></tr><tr><td><code>player_play_operation</code> 的 next/prev/play</td><td>❌ 对我们下发的列表无效</td></tr><tr><td>暂停 / 恢复 / 跳转</td><td><code>pause</code>（media=app_ios）能暂停；暂停期间 <code>status</code> 仍为 1。恢复：<code>play</code>（app_ios / common / 不带 media）、再次 <code>pause</code>、<code>resume</code>、<code>continue</code> 都<strong>不能恢复</strong>（<code>toggle</code> 遇云端卡顿未得出结论）。<code>pause</code>（media=common）不会暂停。跳转：<code>player_set_positon</code> 返回成功但不生效，<code>player_set_position</code> 返回 500。<strong>结论：无法原地恢复，也无法跳转</strong></td></tr><tr><td>列表长度</td><td>181 项（40 KB）可以接受</td></tr><tr><td><code>play_behavior</code></td><td><code>ENQUEUE</code> / <code>REPLACE_ENQUEUED</code> / <code>APPEND</code> 都按替换处理：立即打断当前曲并改播新列表。<strong>不支持追加</strong></td></tr><tr><td>静音哨兵续接</td><td>窗口 [20 s 曲, 60 s 静音]：音箱放完曲目后拉静音，服务端 0.02–0.05 s 内发现并下发新窗口；新窗口只替换静音，未打断任何曲目；曲间多出的静音 = 下发耗时（3 轮：1.4 / 1.7 / 4.0 s）</td></tr><tr><td><code>player_set_loop</code></td><td>0 = 单曲循环；1 = 列表循环；2 = 顺序播完后停止（<code>status</code> 变 0）；3 = 放完继续（随机，待用更多曲目确认）</td></tr><tr><td>音箱什么时候拉流</td><td><strong>在切到该曲时才请求</strong>，误差约 0.4 s；不会提前缓冲下一首。本地文件、Jellyfin（直连/代理）、支持或不支持 Range 的直链、无长度分块、按实时码率推流、YouTube 中转都成立</td></tr><tr><td>请求形态</td><td>有 Content-Length 时同一首会在 0.1 s 内连发 3–4 个请求（读开头后中断、读末尾 128 B 的 ID3 标签、完整下载）；无长度分块只发 1 个</td></tr><tr><td>实时推流</td><td>音箱先缓冲约 4 s 再出声，下一首的请求相应晚约 4 s</td></tr><tr><td>长暂停</td><td>暂停 6 分钟后没有重新请求（整首已缓冲）</td></tr><tr><td>格式</td><td>mp3 / flac / m4a / wav 均可</td></tr><tr><td>现有代理令牌</td><td><code>/proxy/music?urlb64=t.…</code> 只存在内存里，<strong>服务重启后全部失效</strong></td></tr></tbody></table><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p><strong>把歌曲之间的切换交给音箱：服务端一次下发一串曲目，音箱在本地顺序/循环播放；服务端根据音箱的拉流请求跟随当前曲目。只有用户操作才经过小米云。</strong></p><h3 id="组件" tabindex="-1">组件 <a class="header-anchor" href="#组件" aria-label="Permalink to &quot;组件&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SourceResolver（现有 Source 插件，ADR-0003）</span></span>
<span class="line"><span>    只负责：给出一首歌“此刻可用”的真实音频（URL + headers），或说明需要实时转码</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>StreamGateway（新增，xiaomusic 内的 HTTP 端点）</span></span>
<span class="line"><span>    - 每首歌一个稳定地址：/stream/v1/&lt;did&gt;/&lt;queue&gt;/&lt;index&gt;/&lt;source&gt;/&lt;item&gt;?sig=…</span></span>
<span class="line"><span>    - 音箱请求时才调用 SourceResolver；按来源转发、代理或实时转码</span></span>
<span class="line"><span>    - 把同一首歌的一串请求合并成一个 TrackFetched 事件</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>SpeakerQueue（新增，每设备一个）</span></span>
<span class="line"><span>    - 按歌单、播放模式生成要下发的“窗口”（一段曲目）、起始项和 loop_type</span></span>
<span class="line"><span>    - 随机模式由服务端打乱后下发；会话内顺序稳定（沿用 ADR-0004 补充决策）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>PlaybackFollower（新增，每设备一个）</span></span>
<span class="line"><span>    - 消费 TrackFetched，更新当前曲目、开始时间与状态</span></span>
<span class="line"><span>    - 计时器只做兜底</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>SpeakerClient（新增，唯一调用小米云的地方）</span></span>
<span class="line"><span>    - play_queue / stop / set_loop / set_volume / status（只用 MiNA；不提供 TTS）</span></span></code></pre></div><p><code>DevicePlayer</code>（由 <code>device_player.py</code> 拆出）只负责编排：接收命令 → 让 SpeakerQueue 生成列表 → SpeakerClient 下发 → PlaybackFollower 跟随。</p><h3 id="操作行为" tabindex="-1">操作行为 <a class="header-anchor" href="#操作行为" aria-label="Permalink to &quot;操作行为&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>行为</th><th>是否经过云端</th></tr></thead><tbody><tr><td>自动切歌</td><td>音箱本地完成；StreamGateway 收到请求 → TrackFetched → Follower 更新</td><td>否</td></tr><tr><td>点播一首 / 换歌单</td><td>生成新列表，从目标曲开始下发（<code>startaudioid</code>）</td><td>1 次</td></tr><tr><td>手动下一首 / 上一首 / 跳到某首</td><td>重发当前列表，<code>startaudioid</code> 指向目标曲</td><td>1 次</td></tr><tr><td>停止</td><td><code>player_stop</code></td><td>1 次</td></tr><tr><td>改播放模式</td><td>不打断当前曲：只改 <code>loop_type</code>（一次云端调用）；需要重新排序时（切换随机），在下一次 TrackFetched 时以当前曲为起点重发</td><td>1–2 次</td></tr><tr><td>歌单内容同步更新</td><td>标记队列过期，在下一次续接窗口或用户操作时生效</td><td>0–1 次</td></tr><tr><td>窗口放完</td><td>音箱切到窗口末尾的静音哨兵 → 服务端下发下一个窗口（见“窗口与续接”）</td><td>1 次（每个窗口一次）</td></tr></tbody></table><h3 id="播放模式映射" tabindex="-1">播放模式映射 <a class="header-anchor" href="#播放模式映射" aria-label="Permalink to &quot;播放模式映射&quot;">​</a></h3><table tabindex="0"><thead><tr><th>播放模式</th><th>下发窗口</th><th><code>loop_type</code></th></tr></thead><tbody><tr><td>单曲循环</td><td>仅当前曲</td><td>0</td></tr><tr><td>列表循环</td><td>从当前曲起按会话顺序取 N 首（到末尾后接回开头），末尾加静音哨兵</td><td>1</td></tr><tr><td>顺序播放</td><td>从当前曲起取 N 首，末尾加静音哨兵；最后一个窗口到歌单末尾为止、不加哨兵</td><td>2（播完停止）</td></tr><tr><td>单曲播放</td><td>仅当前曲</td><td>2</td></tr><tr><td>随机播放</td><td>服务端打乱后的会话顺序，同列表循环</td><td>1（不使用 3，以保持服务端知道顺序）</td></tr></tbody></table><p>不随机时，列表使用<strong>歌单原本的顺序</strong>（Jellyfin 歌单的编排顺序、本地目录的库顺序），不再按歌名排序。两条播放入口按同一规则生成列表。</p><h3 id="窗口与续接" tabindex="-1">窗口与续接 <a class="header-anchor" href="#窗口与续接" aria-label="Permalink to &quot;窗口与续接&quot;">​</a></h3><p>每次只下发一个窗口（默认 N=20 首，可配置），不下发整个歌单。音箱不支持追加（<code>play_behavior</code> 都按替换处理），任何续接都会替换当前队列，因此续接必须发生在<strong>不在放歌</strong>的时刻：</p><ol><li>需要续接的窗口末尾放一个<strong>静音哨兵</strong>（StreamGateway 提供的固定地址，内容为足够长的静音，例如 60 s）。</li><li>音箱放完窗口最后一首后，会在本地切到哨兵并拉取它；StreamGateway 产生 <code>WindowExhausted</code> 事件。</li><li>服务端立即以下一首为起点下发新窗口。新窗口替换的只是正在播放的静音，不打断任何一首歌。</li><li>歌曲之间多出的静音等于这一次下发的耗时（平时 0.5–1 s，每 N 首一次）。即使小米云卡顿约 31 s，听到的也只是静音；哨兵长度要大于这类卡顿，避免循环回窗口开头。</li><li>若哨兵放完仍未收到新窗口（下发失败），音箱会按 <code>loop_type</code> 回到窗口开头；Follower 会把这次 TrackFetched 识别为“过期窗口”，并重新下发。</li></ol><p>手动操作（点播、切歌、跳歌）总是以目标曲为起点下发一个新窗口；上一首会生成包含前一首的窗口。</p><h3 id="streamgateway-规则" tabindex="-1">StreamGateway 规则 <a class="header-anchor" href="#streamgateway-规则" aria-label="Permalink to &quot;StreamGateway 规则&quot;">​</a></h3><ol><li><strong>地址稳定、重启后仍有效</strong>：地址本身携带 <code>did</code>、队列号、序号、来源和曲目 ID，并用持久化在 <code>conf/</code> 的密钥做 HMAC 签名。服务端重启后，旧队列地址仍能按来源和曲目 ID 解析，不依赖内存里的令牌。</li><li><strong>不能变成开放代理</strong>：只接受签名有效的地址，签名覆盖路径里的全部字段；不接受任意 URL。地址允许音箱匿名访问（音箱无法携带凭据），与现有媒体数据面一致。</li><li><strong>请求合并</strong>：同一 <code>(did, queue, index)</code> 在 3 s 内的请求视为一次拉流。只请求文件末尾的 Range（读取 ID3/索引的探测）不单独算一次切换。<code>Range</code> 起点在文件中段的请求视为续传，不产生 TrackFetched。</li><li><strong>按来源处理</strong>： <ul><li>本地文件：直接提供文件（支持 Range）。</li><li>直链：反向代理并透传 Range。</li><li>Jellyfin：服务端带登录令牌请求，令牌不出现在给音箱的地址里。</li><li>网站来源（YouTube 等）：拉流时才解析、启动实时转码（取代 <code>site_media</code> 在 Source 层调用 <code>RelayRuntime.prepare_link</code>，落实 ADR-0003）。</li><li>在线插件：拉流时才调用插件取地址。</li></ul></li><li><strong>过期队列</strong>：请求的 <code>queue</code> 不是当前队列时，仍然提供音频（音箱可能还在播旧列表的缓冲），同时把事件交给 Follower 判断是否需要重新同步。</li></ol><h3 id="playbackfollower-规则" tabindex="-1">PlaybackFollower 规则 <a class="header-anchor" href="#playbackfollower-规则" aria-label="Permalink to &quot;PlaybackFollower 规则&quot;">​</a></h3><ul><li>TrackFetched 是当前曲目的权威信号；当前曲目的开始时间 = 请求时间（实时转码来源另加约 4 s 缓冲偏移）。</li><li>兜底计时器：按“当前曲时长 + 余量”等待下一次 TrackFetched。超时后查询一次状态：<code>status=0</code> 判定为已停止；否则标记“跟随丢失”，在下一次用户操作时重发列表。</li><li>用户操作发出后，以它产生的第一个 TrackFetched 作为生效确认，取代现在的“开播确认轮询”。</li></ul><h3 id="状态权威-对-adr-0004-的补充" tabindex="-1">状态权威（对 ADR-0004 的补充） <a class="header-anchor" href="#状态权威-对-adr-0004-的补充" aria-label="Permalink to &quot;状态权威（对 ADR-0004 的补充）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>权威</th><th>说明</th></tr></thead><tbody><tr><td>歌单成员</td><td><code>music_library</code></td><td>不变</td></tr><tr><td>设备会话队列（顺序、版本号）</td><td><code>SpeakerQueue</code></td><td>取代 <code>device_player._play_list_items</code></td></tr><tr><td>当前曲目与开始时间</td><td><code>PlaybackFollower</code></td><td>由 TrackFetched 驱动，取代计时器推测与 <code>cur_music</code> 多处写入</td></tr><tr><td>与小米云的通信</td><td><code>SpeakerClient</code></td><td>取代 <code>device_player</code> 中分散的 <code>mina_call</code>；mina/miio 两个空壳 transport 删除或改为包装它</td></tr></tbody></table><h3 id="不提供暂停-恢复" tabindex="-1">不提供暂停 / 恢复 <a class="header-anchor" href="#不提供暂停-恢复" aria-label="Permalink to &quot;不提供暂停 / 恢复&quot;">​</a></h3><p>项目从未规划暂停功能（2026-11-22 Akari 确认），而且实测音箱无法原地恢复、也无法跳转。因此：</p><ul><li>删除 <code>/api/v1/control/pause</code>、<code>/api/v1/control/resume</code>（v1 白名单 24 → 22）、WebUI 中未被页面使用的 <code>pause()</code> / <code>resume()</code>、<code>PlaybackPhase.PAUSED</code> 及相关的 arbiter 意图、transport 方法和测试。</li><li>语音“暂停”维持现状，按停止处理（<code>keywords_stop</code>）。</li><li>用户在音箱上手动暂停时，<code>status</code> 仍为 1，服务端看不出来；兜底计时器到点后若没有新的 TrackFetched，按“跟随丢失”处理。</li></ul><p>✅ 2026-11-23 已删除（第 6 步的第一部分）。语音控制此前已整体删除，上面关于语音“暂停”的一条不再适用。</p><h3 id="不支持队列的硬件" tabindex="-1">不支持队列的硬件 <a class="header-anchor" href="#不支持队列的硬件" aria-label="Permalink to &quot;不支持队列的硬件&quot;">​</a></h3><p><code>play_by_url</code> 路径（不使用 <code>player_play_music</code> 的型号）只能逐首下发。保留现在的逐首模式作为后备，按硬件能力选择；StreamGateway 和 Follower 两种模式共用。</p><h2 id="实施步骤" tabindex="-1">实施步骤 <a class="header-anchor" href="#实施步骤" aria-label="Permalink to &quot;实施步骤&quot;">​</a></h2><p>每一步都要通过行为测试和全量测试，在测试服完整构建并实机验收后再推送。</p><ol><li>✅ <strong>StreamGateway（只读模式）</strong>（2026-11-22 完成：测试服本地/Jellyfin/直链各来源 6 次下发各对应 1 条 <code>track_fetched</code>，重启后地址仍有效）：新增稳定签名地址和请求合并，先只记录 TrackFetched、不改变播放行为；现有下发改用新地址。验收：各来源都能播，日志里 TrackFetched 与切歌一一对应。</li><li>✅ <strong>SpeakerClient</strong>（2026-11-22 完成）：把 <code>mina_call</code> 收进一个类，<code>device_player</code> 改为调用它。行为不变。</li><li>✅ <strong>SpeakerQueue + 队列下发</strong>（2026-11-23 完成）：按播放模式生成列表和 <code>loop_type</code>，自动切歌交给音箱；保留计时器但只做兜底。验收：各播放模式实机连续播放，不再出现重放开头。 <ul><li>实现：<code>xiaomusic/speaker_queue.py</code> 生成窗口；<code>device_player</code> 在 <code>group_player_play</code> 中按窗口下发（<code>player_play_music</code>），StreamGateway 的拉流事件驱动跟随（<code>follow_track</code>，保持 PLAYING，不新增生命周期编号）；哨兵为代码生成的 60 s 静音 MP3（<code>/stream/v1/…/silence/60</code>，序号 = 续接起点）。窗口大小 <code>queue_window_size</code>（环境变量 <code>XIAOMUSIC_QUEUE_WINDOW_SIZE</code>，默认 20，0 = 逐首）。</li><li>兜底计时器在预期结束后 8 s 才触发（单曲循环时不设）；改播放模式时立即改 <code>loop_type</code>，下一次拉流时若音箱所在曲目正是新模式要的下一首就直接跟随，否则重发。</li><li>实测（OH2P）：<code>loop_type</code> 在替换队列后保持不变，只在变化时发送；<code>loop_type=0</code> 时音箱每次重播都会重新拉流（用来重置进度）；窗口续接的静音间隔约 1 s；改为单曲播放后，音箱进入下一首时由服务端停止，停止命令本身约 2.5 s。</li><li>本步顺带落实决策 1 的旧入口部分：<code>update_playlist</code> 不再按歌名排序。v1 API 播放的第一首当时仍逐首下发，已在第 5 步合并。</li></ul></li><li><strong>PlaybackFollower</strong>：当前曲目改由 TrackFetched 驱动；删除逐首计时切歌、开播确认轮询，以及外部链接路径的那一套独立状态；同时删除只为计时器服务的配置 <code>auto_next_confirm_*</code>、<code>auto_next_preplay_stop</code>（2026-11-22 已从设置页撤下），以及固定的切歌提前量 <code>TRACK_END_LEAD_SEC</code>（2026-11-22 取代了 <code>delay_sec</code>）。 <ul><li>✅（2026-11-23，第 5 步之后做）当前曲目由拉流驱动已在第 3 步完成。开播确认改为“音箱拉取起始项”（<code>START_FETCH_TIMEOUT_SEC</code> = 15 s，超时按失败处理）；删除设备层的前台/后台状态轮询、宽限重试、确认观察（<code>ObservationKind</code> 等）、Jellyfin 直连失败改代理、测量用状态探测，以及 coordinator 层从未执行过的状态轮询（设备路径总返回延迟回执）。删除配置 <code>auto_next_confirm_*</code>、<code>auto_next_preplay_stop</code>（自动切歌固定不先停止）。v1 API 的 <code>confirm_start*</code> 选项保留接受、不再起作用。</li><li>与原计划的偏差：逐首计时切歌和 <code>TRACK_END_LEAD_SEC</code> <strong>保留</strong>，只服务仍然逐首下发的情况（不支持 music API 的型号、没有歌单上下文的单独链接、网关不处理的地址）；删掉会让这些情况重新出现“从头重放几秒”。外部链接路径的独立状态（<code>on_external_url_play*</code>）并入第 6 步的拆分清理。</li></ul></li><li><strong>合并入口</strong>：API（外部链接）和本地歌单都走“生成队列 → 下发 → 跟随”这一条路径；<code>site_media</code> 的中转移入 StreamGateway。 <ul><li>✅ 入口合并（2026-11-23）：带歌单上下文的 v1 API 播放（WebUI）从第一首起按窗口下发。API 交来的投递地址（<code>/api/proxy/plugin-url</code>）网关不解析，当前曲改用歌单条目自己的地址（同一首，经网关）。没有歌单上下文的单独链接仍单首下发。实测（随机模式）：第一首即下发 20 首窗口，音箱本地切歌后服务端同秒跟随。</li><li>⏸ <code>site_media</code> 中转移入 StreamGateway：待定。现状是曲库歌单里的网络歌曲走 <code>/proxy</code>，不经过 <code>site_media</code>；<code>site_media</code>（YouTube 等）只用于单独链接的一次性播放，单首下发，<code>/relay/stream</code> 工作正常。移入网关目前只换来“重启后地址仍有效”。</li></ul></li><li><strong>拆分与清理</strong>：<code>device_player.py</code> 拆成 DevicePlayer / SpeakerQueue / PlaybackFollower；把 sid / LifecycleToken / 手动切歌代际 / barrier 收敛为每个队列的版本号；删除暂停/恢复（见“不提供暂停 / 恢复”）；用行为测试替换绑定内部实现的单元测试。 <ul><li>✅ 删除暂停/恢复（2026-11-23）：v1 <code>control/pause</code> / <code>control/resume</code>（白名单 24 → 22）、<code>PlaybackPhase.PAUSED</code> 与 pause/resume 转换、arbiter 的 PAUSE/RESUME 意图（STOP 成为唯一屏障）、transport 与 coordinator/facade 的 pause/resume、设备层的执行函数和 <code>_paused_time</code>、WebUI 调试页按钮与 <code>paused</code> 状态。停止流程里的 <code>player_pause</code>（先暂停再停止）保留。</li><li>✅ 拆分 <code>device_player.py</code>（2026-11-23，第一步，行为不变）：4100 行拆为 <code>device_player.py</code>（编排，约 1170 行）和 <code>xiaomusic/player/</code> 下 8 个 mixin（lifecycle / playlist / queue_dispatch / follower / commands / failure / external_play / library_tasks）。先用 mixin 是为了让依赖私有方法的旧单元测试不变；守护测试改为扫描整个播放器包（<code>tests/player_source.py</code>）。改成对象组合、收敛 sid / LifecycleToken / 手动切歌代际为队列版本号，在后续步骤做。</li><li>待做：按新架构重新设计 API（Akari 2026-11-23：只保留一个 play 接口，来源由路由判断；接口清单先给 Akari 审阅；Home Assistant 经 Node-RED 调用，需同步修改），以及拆分 <code>device_player.py</code>。</li></ul></li></ol><h2 id="待确认问题" tabindex="-1">待确认问题 <a class="header-anchor" href="#待确认问题" aria-label="Permalink to &quot;待确认问题&quot;">​</a></h2><ol><li><code>loop_type=3</code> 的实际顺序（只用两首测过）。</li><li>同一分组多台音箱：每台独立队列，地址里的 <code>did</code> 用于区分；是否需要同步起播待定。</li><li>网站来源在拉流时才解析（约 3.5 s），会增加这一首的起播延迟；可以在前一首开始后预解析下一首，再按需要加入。</li><li>窗口大小 N 的取值：越大续接越少，但每次手动操作的下发越慢（181 项约 3.7 s，3 项约 0.7 s）。先取 20，按实测调整。</li><li><s>静音哨兵的实现</s>：已定（2026-11-23），StreamGateway 用代码生成 60 s 静音 MP3（MPEG-1 Layer III 32 kbps 单声道帧，不依赖 ffmpeg），OH2P 实测可播。如遇超过 60 s 的云端卡顿再加长。</li></ol><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><h3 id="正面" tabindex="-1">正面 <a class="header-anchor" href="#正面" aria-label="Permalink to &quot;正面&quot;">​</a></h3><ul><li>自动切歌不再依赖小米云，云端卡顿和“从头播几秒”不再出现在自动切歌中。</li><li>当前曲目由真实拉流请求确定，不再靠计时器推测。</li><li>各播放源对音箱是同一种地址，来源差异收在 Source 和 StreamGateway 两层。</li><li>播放模式交给音箱原生实现，顺序/单曲播放的“末尾停止”不再需要服务端发命令。</li><li>两条播放入口和多套过时判断机制可以收敛为一条路径、一个队列版本号。</li></ul><h3 id="负面" tabindex="-1">负面 <a class="header-anchor" href="#负面" aria-label="Permalink to &quot;负面&quot;">​</a></h3><ul><li>音频流全部经过 xiaomusic 中转，服务端要承担流量（局域网内）和一个新的常驻组件。</li><li>手动操作仍然经过小米云，体验与现在相同（偶发卡顿依然存在）。</li><li>迁移期间逐首模式与队列模式并存，需要按硬件能力切换并分别测试。</li></ul>`,46)]))}const y=t(l,[["render",r]]);export{h as __pageData,y as default};
